param([Parameter(Mandatory=$true)][string]$PackageRoot,[string]$CloudArchive,[string]$DecoderExecutable)
$ErrorActionPreference='Stop'
$repo=Split-Path -Parent $PSScriptRoot;$out=Join-Path $PSScriptRoot ('output\import-update-'+[guid]::NewGuid().ToString('N'));$null=New-Item -ItemType Directory -Path $out
$files=@('Manager.cs','IconAssets.cs','WallpaperLibrary.cs','GalleryControls.cs','GalleryManager.cs','MediaPreviewJob.cs','SoftwareUpdate.cs','ManagerUpdates.cs','ManagerPetAppearance.cs','ManagerFollow.cs','CodexFollow.cs','PetCardPalette.cs','DailyUpdates.cs','CloudPets.cs','BuiltinDownloads.cs','CompanionCore.cs','WindowResize.cs','CompanionBehavior.cs','CompanionVideo.cs','CompanionOverlay.cs','CompanionSettings.cs','CompanionQuota.cs','CompanionWindow.cs','CompanionPage.cs','CompanionActivity.cs','CompanionBailong.cs','CompanionTokens.cs','HubPopupMenu.cs')|ForEach-Object{Join-Path $repo ('source\'+$_)}
$exe=Join-Path $PackageRoot 'ImportUpdateTests.exe';$report=Join-Path $out 'result.json'
& (Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe') /nologo /target:winexe /main:ImportUpdateTests /platform:x64 /codepage:65001 ("/out:$exe") /r:System.Windows.Forms.dll /r:System.Drawing.dll /r:System.Web.Extensions.dll /r:Accessibility.dll /r:System.IO.Compression.dll /r:System.IO.Compression.FileSystem.dll $files (Join-Path $PSScriptRoot 'ImportUpdateTests.cs')
if($LASTEXITCODE -ne 0){throw 'Import/update tests failed to compile'}
try{$process=Start-Process -FilePath $exe -ArgumentList ('"'+$report+'" "'+$PackageRoot+'" "'+$CloudArchive+'" "'+$DecoderExecutable+'"') -WindowStyle Hidden -PassThru;if(-not $process.WaitForExit(60000)){throw 'Import/update tests timed out'};$result=Get-Content -LiteralPath $report -Raw|ConvertFrom-Json;if($process.ExitCode -ne 0 -or -not $result.pass){throw $result.error};$result|ConvertTo-Json -Depth 6 -Compress;Write-Output ('Report: '+$report)}finally{Remove-Item -LiteralPath $exe -Force -ErrorAction SilentlyContinue}
